-- ESQUEMA ACTUAL DE LA APLICACION MOVIL PARA POSTGRESQL / NEON
-- Solo para una base vacia dedicada a la app; nunca sobre una instalacion existente.
-- Generado con scripts/exportar-esquema-movil.py desde el estado final de migraciones.
-- Las ventas se cobran en su totalidad por monto_venta y fecha_venta.
-- No incluye usuarios, credenciales ni datos de ejemplo.
-- Para actualizar una base existente usa: manage.py migrate movil --database=movil.
BEGIN;
SET LOCAL search_path TO public;
DO $verificar_destino$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_catalog.pg_class AS c
        JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S')
    ) THEN
        RAISE EXCEPTION 'La base contiene tablas, vistas o secuencias. Usa las migraciones Django para actualizarla.';
    END IF;
END;
$verificar_destino$;
CREATE TABLE "movil_limiteacceso" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "clave_hash" varchar(64) NOT NULL UNIQUE, "ventana" bigint NOT NULL, "cantidad" integer NOT NULL CHECK ("cantidad" >= 0), "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "movil_organizacion" ("id" uuid NOT NULL PRIMARY KEY, "nombre" varchar(120) NOT NULL, "descripcion" varchar(2000) NOT NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "movil_gastooperativo" ("id" uuid NOT NULL PRIMARY KEY, "concepto" varchar(150) NOT NULL, "monto_mensual" numeric(12, 2) NOT NULL, "activo" boolean NOT NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL, "organizacion_id" uuid NOT NULL, CONSTRAINT "movil_gasto_monto_no_negativo" CHECK ("monto_mensual" >= 0));
CREATE TABLE "movil_cliente" ("id" uuid NOT NULL PRIMARY KEY, "nombre" varchar(150) NOT NULL, "correo" varchar(254) NOT NULL, "telefono" varchar(25) NOT NULL, "comentarios" varchar(2000) NOT NULL, "hubo_venta" boolean NOT NULL, "monto_venta" numeric(12, 2) NULL, "descripcion_servicio" varchar(2000) NOT NULL, "fecha_venta" date NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL, "organizacion_id" uuid NOT NULL, CONSTRAINT "movil_monto_venta_positivo" CHECK (("monto_venta" IS NULL OR "monto_venta" > 0)), CONSTRAINT "movil_venta_tiene_importe" CHECK ((NOT ("hubo_venta") OR "monto_venta" IS NOT NULL)));
CREATE TABLE "movil_requerimiento" ("id" uuid NOT NULL PRIMARY KEY, "orden" smallint NOT NULL CHECK ("orden" >= 0), "titulo" varchar(150) NOT NULL, "descripcion" varchar(2000) NOT NULL, "estado" varchar(20) NOT NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL, "cliente_id" uuid NOT NULL, CONSTRAINT "movil_requerimiento_orden_unico" UNIQUE ("cliente_id", "orden"), CONSTRAINT "movil_requerimiento_orden_valido" CHECK (("orden" >= 1 AND "orden" <= 100)), CONSTRAINT "movil_requerimiento_estado_valido" CHECK ("estado" IN ('por_hacer', 'en_progreso', 'completado')));
CREATE TABLE "movil_usuario" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre_completo" varchar(150) NOT NULL, "usuario" varchar(80) NOT NULL UNIQUE, "correo" varchar(254) NOT NULL UNIQUE, "telefono" varchar(15) NOT NULL UNIQUE, "contrasena_hash" varchar(255) NOT NULL, "activo" boolean NOT NULL, "intentos_fallidos" smallint NOT NULL CHECK ("intentos_fallidos" >= 0), "bloqueado_hasta" timestamp with time zone NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "movil_sesion" ("id" uuid NOT NULL PRIMARY KEY, "token_hash" varchar(64) NOT NULL UNIQUE, "creado_en" timestamp with time zone NOT NULL, "expira_en" timestamp with time zone NOT NULL, "revocado_en" timestamp with time zone NULL, "usuario_id" bigint NOT NULL);
CREATE TABLE "movil_membresia" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "rol" varchar(20) NULL, "estado" varchar(20) NOT NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL, "organizacion_id" uuid NOT NULL, "usuario_id" bigint NOT NULL, CONSTRAINT "movil_miembro_organizacion_unico" UNIQUE ("usuario_id", "organizacion_id"), CONSTRAINT "movil_estado_membresia_valido" CHECK ("estado" IN ('pendiente', 'aceptado', 'rechazado', 'eliminado')), CONSTRAINT "movil_rol_valido" CHECK (("rol" IS NULL OR "rol" IN ('admin', 'desarrollador', 'crm', 'finanzas'))), CONSTRAINT "movil_miembro_aceptado_tiene_rol" CHECK ((NOT ("estado" = 'aceptado') OR "rol" IS NOT NULL)));
CREATE TABLE "movil_gastohistorial" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "vigente_desde" date NOT NULL, "concepto" varchar(150) NOT NULL, "monto_mensual" numeric(12, 2) NOT NULL, "actualizado_en" timestamp with time zone NOT NULL, "gasto_id" uuid NOT NULL, CONSTRAINT "movil_gasto_historial_mes_unico" UNIQUE ("gasto_id", "vigente_desde"), CONSTRAINT "movil_gasto_historial_no_negativo" CHECK ("monto_mensual" >= 0));
CREATE INDEX "movil_limiteacceso_clave_hash_4a2defb9_like" ON "movil_limiteacceso" ("clave_hash" varchar_pattern_ops);
